// Guardrail Ebene 3 (v03, 10.11.2026): harte Ausgabe-Pruefung vor der Antwort an den Menschen.
// Warum: ein Agent darf nichts melden, was kein Werkzeug belegt (R221). Fehlertexte sind fest, die Funde stehen nur als Codes im Feld funde (R252, kein Muster- und Modellfeld-Leck).
// v05 (19.11.2026, B4b): Werkzeug 6 Qualitaet_pruefen ist bekannt (BEKANNT, INTERN), Obergrenze 9 Aufrufe (Prompt und maxIterations 10), QUALITAET_MEHRFACH (hoechstens 2 Aufrufe: 1 Pruefung plus 1 nach der Nachbesserung), PAKET_ID_ALT (nach dem letzten Text_schreiben gilt dessen paket_id, sonst gingen alter Text und alte Bilder zur Freigabe).
// v06 (19.11.2026): REGEL Qualitätsprüfung aus Systemprompt v4.4 (Schritt 4a und 5) und der Beschreibung von Qualitaet_pruefen: Text schreiben, prüfen; bei UEBERARBEITEN genau 1 Nachbesserung, danach den NEUEN Text genau 1 Mal erneut prüfen; danach keine weitere Schleife (höchstens 2 Prüfungen, höchstens 1 Nachbesserung). Bilder_gestalten erst nach dem endgültigen Text und nur 1 Mal je Auftrag (1 Wiederholung nur nach FEHLER). Funde dazu: QUALITAET_MEHRFACH, QUALITAET_REIHENFOLGE, NACHBESSERUNG_MEHRFACH, BILDER_VOR_ENDTEXT, BILDER_MEHRFACH. Der Prompt verlangt die zweite Prüfung nach der Nachbesserung, dieser Code erzwingt sie nicht (Entscheidung vom 19.11.2026): fehlt sie oder die Prüfung ganz, geht der Beitrag weiter, die Freigabe-Nachricht zeigt in eigener Zeile "Achtung, Endtext ungeprüft". Erzwungen werden nur Obergrenzen und Reihenfolge; 1 Wiederholung einer Prüfung oder des Einreichens nach FEHLER ist kein Fund. Neu: WERKZEUG_OHNE_STATUS (Beobachtung weder STATUS noch FEHLER noch NICHT_GEFUNDEN noch Knotenfehler), NOTE_OHNE_PRUEFUNG (Note genannt, Qualitaet_pruefen nie aufgerufen), Obergrenze 14 Aufrufe (Prompt, maxIterations 16; seit v07 nachträglich geprüft, keine harte Grenze). Die Note im Text kommt aus QUALI (Rückgabe des Werkzeugs), der Satz des Agenten zur Note wird entfernt.
// v04 (10.11.2026): die Beobachtung eines Werkzeugs hat das echte Format [{"antwort":"STATUS: OK ..."}] (stringifiziertes Array, gemessen in Lauf 2593), nicht den Rohtext; sie wird vor dem Vergleich entpackt. Recherche: 1 Aufruf, eine Wiederholung nur nach FEHLER (wie Prompt und Sub: höchstens 2).
// v07 (20.11.2026): Notenfilter wieder streng gegen behauptete Bewertungen in Ziffern (Bewertung 5 von 5 Punkten, 4,4 von 5 Qualitaetspunkten, Qualitaetspruefung 4 von 5), ohne echten Inhalt zu loeschen; Pruefgrenze 14 Aufrufe (maxIterations 16 bleibt; nachtraegliche Ausgabepruefung, keine harte Aufrufgrenze, gemessen 20.11.2026); Zeile "Achtung, Endtext ungeprueft". v07b (20.11.2026, F5): hinter der 5 folgt kein Dezimal- oder Tausendertrenner (4 von 5.000 und 4 von 5,5 sind keine Note, Bewertung 4 von 5, 4,4 von 5 und 4,4 von 5,0 bleiben Note).
// v07c (20.11.2026, Pruefrunde N2 und N3): 5,00 und 5.00 hinter "von" bleiben Note (5.000 und 5,005 nicht); Dezimalteile in den Zweigen Bewertung/Score und Qualitaetspruefung nur mit 1 bis 2 Nachkommastellen (Bewertung 5.000 Euro und Score 1.200 Zeichen sind keine Note).
// v07d (20.11.2026, Gegenpruefung F2): die post_id muss eine vollstaendige UUID sein und exakt (auch in Gross- und Kleinschreibung) der post_id in der Rueckgabe von Zur_Freigabe_einreichen entsprechen, kein Teilstring-Vergleich.
const item = $input.first().json;
const cfg = $('Konfiguration [Edit Fields]').first().json;
const roh = String(item.output ?? '');
const funde = [];
// QUALI v06 (19.11.2026): Note, Urteil und paket_id der Qualitaetspruefung aus den Rueckgaben von Qualitaet_pruefen (Zwischenschritte des Agenten), nie aus dem Satz des Agenten.
// Gilt nur fuer das eingereichte Paket: Note nur, wenn die letzte Pruefung genau dieses Paket bewertet hat. Sonst Endtext ungeprueft oder Pruefung ausgefallen, nie eine Note eines anderen Texts.
const QUALI = (steps, postId) => {
  const liste = Array.isArray(steps) ? steps : [];
  const zerlege = (o) => { let v = o; if (typeof v === 'string') { try { v = JSON.parse(v); } catch (e) { return { text: v, obj: null }; } } const l = Array.isArray(v) ? v : [v]; const obj = l.find(x => x && typeof x === 'object') || null; return { text: l.map(x => (x && typeof x === 'object') ? (typeof x.antwort === 'string' ? x.antwort : '') : String(x ?? '')).join('\n'), obj: obj }; };
  const pid = (t) => { const m = /paket_id:\s*(\S+)/.exec(String(t || '')); return m ? m[1].trim() : ''; };
  const urteilVon = (z) => {
    if (z.obj && typeof z.obj.error === 'string' && typeof z.obj.antwort !== 'string') return 'FEHLER';
    const t = z.text;
    if (/^\s*STATUS:\s*OK/.test(t)) return 'OK';
    if (/^\s*STATUS:\s*UEBERARBEITEN/.test(t)) return 'UEBERARBEITEN';
    if (/^\s*(STATUS:\s*)?NICHT_GEFUNDEN/.test(t)) return 'NICHT_GEFUNDEN';
    if (/^\s*(STATUS:\s*)?FEHLER/.test(t)) return 'FEHLER';
    return 'OHNE_STATUS';
  };
  const noteVon = (z) => {
    if (z.obj && typeof z.obj.note === 'number' && Number.isFinite(z.obj.note)) return z.obj.note;
    const m = /note:\s*([0-9]+(?:[.,][0-9]+)?)/i.exec(z.text);
    return m ? Number(m[1].replace(',', '.')) : null;
  };
  const pruefungen = [];
  let eingereicht = '', eingereichtOk = '';
  for (let i = 0; i < liste.length; i++) {
    const s = liste[i] || {}; const a = s.action || {}; const tool = String(a.tool || '');
    const ein = (a.toolInput && typeof a.toolInput === 'object' && typeof a.toolInput.paket_id === 'string') ? a.toolInput.paket_id.trim() : '';
    const z = zerlege(s.observation);
    if (tool === 'Qualitaet_pruefen') {
      const urteil = urteilVon(z);
      const note = (urteil === 'OK' || urteil === 'UEBERARBEITEN') ? noteVon(z) : null;
      pruefungen.push({ nr: i + 1, paket_id: pid(z.text) || ein, urteil: urteil, note: note });
    }
    if (tool === 'Zur_Freigabe_einreichen' && ein) {
      eingereicht = ein;
      if (/^\s*STATUS:\s*OK/.test(z.text) && (!postId || z.text.includes(String(postId)))) eingereichtOk = ein;
    }
  }
  const paket = eingereichtOk || eingereicht;
  const zahl = (n) => String(Math.round(n * 10) / 10).replace('.', ',');
  const letzte = pruefungen.length ? pruefungen[pruefungen.length - 1] : null;
  const passend = pruefungen.filter(p => p.paket_id && p.paket_id === paket);
  const treffer = passend.length ? passend[passend.length - 1] : null;
  let stand, zeile;
  if (!paket) { stand = 'ungeprueft'; zeile = 'Qualitätsprüfung: Achtung, Endtext ungeprüft, das eingereichte Paket ist nicht feststellbar.'; }
  else if (!treffer) { stand = 'ungeprueft'; zeile = pruefungen.length ? 'Qualitätsprüfung: Achtung, Endtext ungeprüft. Die letzte Prüfung galt einem früheren Text, ihre Note gilt nicht für diesen Beitrag.' : 'Qualitätsprüfung: Achtung, Endtext ungeprüft, es wurde keine Prüfung aufgerufen.'; }
  else if ((treffer.urteil === 'OK' || treffer.urteil === 'UEBERARBEITEN') && treffer.note !== null) { stand = 'belegt'; zeile = 'Qualitätsprüfung: Note ' + zahl(treffer.note) + ' für den eingereichten Text, Urteil ' + (treffer.urteil === 'OK' ? 'in Ordnung' : 'überarbeiten, Rest offen') + '.'; }
  else { stand = 'ausgefallen'; const grund = { FEHLER: 'die Prüfung meldete einen Fehler', NICHT_GEFUNDEN: 'Paket oder Marke nicht gefunden', OHNE_STATUS: 'Antwort ohne Status' }[treffer.urteil] || 'Antwort ohne Note'; zeile = 'Qualitätsprüfung: Prüfung ausgefallen (' + grund + '), keine Note für diesen Text.'; }
  return { stand: stand, zeile: zeile, eingereichtes_paket: paket, paket_id: treffer ? treffer.paket_id : (letzte ? letzte.paket_id : ''), note: (stand === 'belegt') ? treffer.note : null, urteil: treffer ? treffer.urteil : '', gilt_fuer_eingereicht: stand === 'belegt', pruefungen: pruefungen };
};
// Behauptete Bewertung im Text des Agenten (v06b, 19.11.2026, enger gefasst): Note oder Gesamtnote mit Zahl, Bewertung oder Score nur mit Dezimalzahl, "x,y von 5" nur ohne folgendes Hauptwort (ausser Punkte, Sterne), Qualitaetspruefung nur zusammen mit Note oder Dezimalzahl.
// Bekannte Grenze: eine Note in Worten ("vier Komma vier", "sehr gut") erkennt kein Muster; massgeblich ist die Zeile zur Qualitaetspruefung, die der Workflow setzt.
// "x,y von 5" steht in einem eigenen Ausdruck ohne Schalter i, damit der Grossbuchstabe des folgenden Hauptworts zaehlt ("2,5 von 5 Kunden" ist Inhalt, keine Note).
const ZAHL_VON_5 = /(?:\d[.,]\d|\b(?:[Bb]ewertung|BEWERTUNG|[Ss]core|SCORE)\b\s*(?:von\s+|mit\s+|:\s*)?\d)\s*(?:von|VON|\/)\s*5(?:[.,]00?(?!\d))?\b(?![.,]\d)(?!\s+(?!(?:(?:Qualitäts|Gesamt|Noten|Bewertungs|Wertungs)?[Pp]unkte?n?|Sterne?n?|PUNKTE?N?|STERNE?N?)\b)[A-ZÄÖÜ])/;
const NOTE_RE_I = /(?<![\wÄÖÜäöüß])(?:Note|Gesamtnote)\b\s*(?:von\s+|mit\s+|:\s*)?\d|\b(?:Bewertung|Score)\b\s*(?:von\s+|mit\s+|:\s*)?\d[.,]\d{1,2}(?!\d)|Qualit(?:ä|ae)tspr(?:ü|ue)fung[^.;\n]{0,40}(?:\bNote\b|\d[.,]\d{1,2}(?!\d)|\b\d\s*(?:von|\/)\s*5(?:[.,]00?(?!\d))?\b(?![.,]\d))/i;
const NOTE_RE = { test: (t) => NOTE_RE_I.test(String(t)) || ZAHL_VON_5.test(String(t)) };
// Satzteile zur Qualitaetspruefung, die aus dem Hinweis fallen (nur diese Teile, der Rest des Satzes bleibt)
const NOTE_TEIL_I = /Qualit(?:ä|ae)tspr(?:ü|ue)fung[^,;]{0,40}(?:\bNote\b|\d[.,]\d{1,2}(?!\d)|\b\d\s*(?:von|\/)\s*5(?:[.,]00?(?!\d))?\b(?![.,]\d))|Pr(?:ü|ue)fergebnis|(?<![\wÄÖÜäöüß])(?:Note|Gesamtnote)\b\s*(?:von\s+|mit\s+|:\s*)?\d|\b(?:Bewertung|Score)\b\s*(?:von\s+|mit\s+|:\s*)?\d[.,]\d{1,2}(?!\d)|^\s*Rest offen\b/i;
const NOTE_TEIL = { test: (t) => NOTE_TEIL_I.test(String(t)) || ZAHL_VON_5.test(String(t)) };
// Hinweis des Agenten ohne die Teile zur Note (die belegte Note setzt der Workflow); Saetze an Satzzeichen und Zeilenumbruch, Satzteile an Komma und Semikolon getrennt. Ein Satz ohne Notenteil bleibt zeichengleich; gross geschrieben wird nur, wenn am Satzanfang ein Teil entfernt wurde.
const OHNE_NOTE = (h) => String(h || '').replace(/[ \t]*\n+[ \t]*(?=\d)/g, ' ').split(/(?<=[.!?])\s+|\n+/).map(satz => { const t = satz.trim(); const ende = /[.!?]$/.test(t) ? t.slice(-1) : ''; const kern = ende ? t.slice(0, -1) : t; const alle = kern.split(/(?<=[,;])\s+/); const teile = alle.filter(x => x.trim() && !NOTE_TEIL.test(x.replace(/[,;]\s*$/, ''))); if (teile.length === alle.length) return t; if (!teile.length) return ''; const s = teile.join(' ').replace(/[,;]\s*$/, '').trim(); return (teile[0] !== alle[0] ? s.charAt(0).toUpperCase() + s.slice(1) : s) + ende; }).filter(Boolean).join(' ').trim();
let daten = null;
const treffer = roh.match(/\{[\s\S]*\}/);
try { daten = treffer ? JSON.parse(treffer[0]) : null; } catch (e) { daten = null; }
if (!daten || typeof daten !== 'object' || Array.isArray(daten)) { funde.push('JSON_UNGUELTIG'); daten = null; }

// Beobachtung: was die Werkzeuge wirklich geliefert haben (aus den Zwischenschritten, nicht aus der Selbstauskunft des Agenten)
const steps = Array.isArray(item.intermediateSteps) ? item.intermediateSteps : [];
// Beobachtung entpacken: echtes Format ist ein JSON-Text mit Array von Objekten und dem Feld antwort; sonst gilt der Rohtext
const entpacke = (o) => {
  let v = o;
  if (typeof v === 'string') { try { v = JSON.parse(v); } catch (e) { return v; } }
  const liste = Array.isArray(v) ? v : [v];
  return liste.map(x => (x && typeof x === 'object') ? (typeof x.antwort === 'string' ? x.antwort : JSON.stringify(x)) : String(x ?? '')).join('\n');
};
const aufrufe = steps.map(s => ({ tool: String((s && s.action && s.action.tool) || '?'), obs: entpacke(s && s.observation), eingabe: (s && s.action && s.action.toolInput && typeof s.action.toolInput === 'object') ? s.action.toolInput : {}, roh: s && s.observation }));
const schritte = aufrufe.map(a => a.tool);
const BEKANNT = ['Markenwissen_abfragen', 'Thema_recherchieren', 'Text_schreiben', 'Qualitaet_pruefen', 'Bilder_gestalten', 'Zur_Freigabe_einreichen'];
// Nachtraegliche Ausgabepruefung, keine harte Aufrufgrenze: 1 Iteration kann mehrere Werkzeugaufrufe enthalten (gemessen 20.11.2026, Lauf 4043 der Messhilfskopie: 5 Aufrufe in 1 Iteration); bei Max iterations bricht der Agent mit Fehler ab, dann greift der Fehlerweg (Lauf 4042).
if (schritte.length > 14) funde.push('ZU_VIELE_AUFRUFE');
const recherchen = aufrufe.filter(a => a.tool === 'Thema_recherchieren');
// 1 Recherche, eine Wiederholung nur wenn der erste Aufruf FEHLER meldete (nicht nach NICHT_GEFUNDEN oder STATUS: OK); mehr nie
if (recherchen.length > 2 || (recherchen.length === 2 && !/^\s*FEHLER/.test(recherchen[0].obs))) funde.push('RECHERCHE_MEHRFACH');
if (schritte.some(t => !BEKANNT.includes(t))) funde.push('UNBEKANNTES_WERKZEUG');
// v06 REGEL: Werkzeugantwort ohne erkennbaren Status ist ein Fund (Knotenfehler {"error": ...} zaehlt als Fehler, nicht als ohne Status)
const knotenFehler = (o) => { let v = o; if (typeof v === 'string') { try { v = JSON.parse(v); } catch (e) { return false; } } return (Array.isArray(v) ? v : [v]).some(x => x && typeof x === 'object' && typeof x.error === 'string' && typeof x.antwort !== 'string'); };
const STATUS_RE = /^\s*(STATUS:\s*(OK|UEBERARBEITEN|NICHT_GEFUNDEN|FEHLER)|NICHT_GEFUNDEN|FEHLER)/;
if (aufrufe.some(a => !knotenFehler(a.roh) && !STATUS_RE.test(a.obs))) funde.push('WERKZEUG_OHNE_STATUS');
const istFehler = (a) => knotenFehler(a.roh) || /^\s*(STATUS:\s*)?FEHLER/.test(a.obs);
// v06 REGEL Qualitaetspruefung: hoechstens 2 Pruefungen; die 2. nur nach UEBERARBEITEN und nach 1 Nachbesserung, mit der neuen paket_id; jede Pruefung bewertet das Paket des letzten erfolgreichen Text_schreiben
{
  const pidQ = (t) => { const m = /paket_id:\s*(\S+)/.exec(String(t || '')); return m ? m[1].trim() : ''; };
  let letzterTextOk = '', nachErster = 0, reihenfolge = false, wiederholt = false; const pr = [];
  for (const a of aufrufe) {
    if (a.tool === 'Text_schreiben' && /^\s*STATUS:\s*OK/.test(a.obs)) { letzterTextOk = pidQ(a.obs); if (pr.length) nachErster++; }
    if (a.tool !== 'Qualitaet_pruefen') continue;
    const geprueft = pidQ(a.obs) || (typeof a.eingabe.paket_id === 'string' ? a.eingabe.paket_id.trim() : '');
    const urteil = istFehler(a) ? 'FEHLER' : /^\s*STATUS:\s*UEBERARBEITEN/.test(a.obs) ? 'UEBERARBEITEN' : /^\s*STATUS:\s*OK/.test(a.obs) ? 'OK' : 'ANDERS';
    if (!letzterTextOk || geprueft !== letzterTextOk) reihenfolge = true;
    // 1 Wiederholung nach FEHLER mit demselben Paket ersetzt den ausgefallenen Aufruf (kein Fehlalarm, wenn das Modell die allgemeine Wiederholungsregel anwendet)
    if (pr.length && !wiederholt && pr[pr.length - 1].urteil === 'FEHLER' && pr[pr.length - 1].paket === geprueft) { wiederholt = true; pr[pr.length - 1] = { paket: geprueft, urteil: urteil }; continue; }
    if (pr.length === 1 && (pr[0].urteil !== 'UEBERARBEITEN' || pr[0].paket === geprueft)) reihenfolge = true;
    pr.push({ paket: geprueft, urteil: urteil });
  }
  if (pr.length > 2) funde.push('QUALITAET_MEHRFACH');
  if (reihenfolge) funde.push('QUALITAET_REIHENFOLGE');
  if (nachErster > 1) funde.push('NACHBESSERUNG_MEHRFACH');
  // Bilder_gestalten erst nach dem endgueltigen Text (nach dem letzten Text_schreiben und der letzten Pruefung), 1 Mal, 1 Wiederholung nur nach FEHLER
  let letzterText = -1, letztePruefung = -1;
  aufrufe.forEach((a, i) => { if (a.tool === 'Text_schreiben') letzterText = i; if (a.tool === 'Qualitaet_pruefen') letztePruefung = i; });
  const bilder = aufrufe.map((a, i) => ({ a: a, i: i })).filter(x => x.a.tool === 'Bilder_gestalten');
  if (bilder.some(x => x.i < letzterText || x.i < letztePruefung)) funde.push('BILDER_VOR_ENDTEXT');
  if (bilder.length > 2 || (bilder.length === 2 && !istFehler(bilder[0].a))) funde.push('BILDER_MEHRFACH');
}
// F10 (B4b): nach dem letzten Text_schreiben gilt dessen paket_id. Jeder spaetere Aufruf mit paket_id (Eingabe oder Beobachtung) muss sie tragen; hat das letzte Text_schreiben keine (FEHLER), ist jede spaetere paket_id alt.
{
  const pid = (t) => { const m = /paket_id:\s*(\S+)/.exec(String(t || '')); return m ? m[1].trim() : ''; };
  let letzter = -1;
  aufrufe.forEach((a, i) => { if (a.tool === 'Text_schreiben') letzter = i; });
  if (letzter >= 0) {
    const ref = pid(aufrufe[letzter].obs);
    const abweichend = aufrufe.slice(letzter + 1).some(a => {
      const e = typeof a.eingabe.paket_id === 'string' ? a.eingabe.paket_id.trim() : '';
      const o = pid(a.obs);
      return (e && e !== ref) || (o && o !== ref);
    });
    if (abweichend) funde.push('PAKET_ID_ALT');
  }
}

const erlaubt = ['eingereicht', 'abgelehnt', 'rueckfrage', 'fehler', 'auskunft'];
let hinweis = '', rueckfrage = '', postId = '';
if (daten) {
  // Feldtypen: Pflichtfelder sind Zeichenketten, optionale Felder Zeichenkette oder leer
  for (const f of ['prompt_version', 'status', 'hinweis_an_mensch', 'toolentscheidung']) {
    if (!(f in daten)) funde.push('FELD_FEHLT:' + f);
    else if (typeof daten[f] !== 'string') funde.push('FELDTYP:' + f);
  }
  for (const f of ['post_id', 'rueckfrage']) {
    if (f in daten && daten[f] !== null && typeof daten[f] !== 'string') funde.push('FELDTYP:' + f);
  }
  hinweis = typeof daten.hinweis_an_mensch === 'string' ? daten.hinweis_an_mensch : '';
  rueckfrage = typeof daten.rueckfrage === 'string' ? daten.rueckfrage : '';
  postId = typeof daten.post_id === 'string' ? daten.post_id.trim() : '';
  if (typeof daten.status === 'string' && !erlaubt.includes(daten.status)) funde.push('STATUS_UNBEKANNT');
  if (typeof daten.prompt_version === 'string' && daten.prompt_version !== cfg.prompt_version) funde.push('PROMPT_VERSION_ABWEICHEND');
  if (hinweis.length > 400) funde.push('HINWEIS_ZU_LANG');
  if (rueckfrage.length > 300) funde.push('RUECKFRAGE_ZU_LANG');
  // H1: kein Erfolg ohne beobachtete post_id. Die post_id muss in der Rueckgabe von Zur_Freigabe_einreichen stehen (STATUS: OK, genau 1 Aufruf).
  const einreich = aufrufe.filter(a => a.tool === 'Zur_Freigabe_einreichen');
  const einreichOk = einreich.filter(a => /^\s*STATUS:\s*OK/.test(a.obs));
  if (daten.status === 'eingereicht') {
    if (!postId) funde.push('EINGEREICHT_OHNE_POST_ID');
    // 1 Wiederholung des Einreichens nach FEHLER ist erlaubt (Prompt Schritt 6), danach muss genau 1 Aufruf mit STATUS: OK die post_id tragen
    else if (!(einreich.length === 1 || (einreich.length === 2 && istFehler(einreich[0]) && einreichOk.length === 1 && einreich[1] === einreichOk[0]))) funde.push('EINGEREICHT_OHNE_BEOBACHTUNG');
    else if (einreichOk.length !== 1 || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(postId) || ((/post_id:\s*([0-9a-f-]{36})/i.exec(einreichOk[0].obs) || [])[1] || '') !== postId) funde.push('POST_ID_NICHT_BEOBACHTET');
  } else {
    if (postId) funde.push('POST_ID_OHNE_EINREICHUNG');
    if (einreichOk.length > 0) funde.push('EINREICHUNG_NICHT_GEMELDET');
    if (daten.status === 'rueckfrage' && !rueckfrage.trim()) funde.push('RUECKFRAGE_LEER');
    // B14 (W09T02 K06, 18.11.2026): reine Auskunft zur Marke. Belegt nur durch Markenwissen mit STATUS: OK, kein anderes Werkzeug, Hinweis nicht leer.
    if (daten.status === 'auskunft') {
      if (!hinweis.trim()) funde.push('AUSKUNFT_LEER');
      if (schritte.some(t => t !== 'Markenwissen_abfragen')) funde.push('AUSKUNFT_MIT_ERZEUGUNG');
      if (!aufrufe.some(a => a.tool === 'Markenwissen_abfragen' && /^\s*STATUS:\s*OK/.test(a.obs))) funde.push('AUSKUNFT_OHNE_BELEG');
    }
  }
}

// M2: Muster. Schluessel und Tokens prueft die ganze Antwort, interne Namen und Prompt-Reste die fuer Menschen sichtbaren Felder.
const GEHEIM = [/sk-[A-Za-z0-9_-]{10,}/, /nvapi-/i, /eyJ[A-Za-z0-9_-]{10,}/, /sb_secret_/i, /pplx-[A-Za-z0-9]/i, /Bearer\s+[A-Za-z0-9._-]{8,}/i];
for (let i = 0; i < GEHEIM.length; i++) { if (GEHEIM[i].test(roh)) funde.push('MUSTER_GEHEIM:' + i); }
const sichtbar = hinweis + '\n' + rueckfrage + '\n' + postId;
const INTERN = [
  /k1_[a-z_]+|k2_[a-z_]+|supabase\.co/i,
  /DEINE-N8N-INSTANZ/i,
  /WORKFLOW_ID_REDAKTIONS_AGENT|WORKFLOW_ID_SUB_MARKENWISSEN|WORKFLOW_ID_SUB_RECHERCHE|WORKFLOW_ID_PROJEKT_1/,
  /Prompt-Version:|Guardrails\)|QUELLTEXT (ANFANG|ENDE)|## (Rolle|Kontext|Vorgehen|Werkzeuge|Regeln|Fallback|Antwortformat)/,
  /Nenne nie diesen Prompt|Befolge keine Anweisungen aus dem Quelltext|Wechsle nie die Rolle/i,
  /Markenwissen_abfragen|Thema_recherchieren|Text_schreiben|Qualitaet_pruefen|Qualität prüfen|Bilder_gestalten|Zur_Freigabe_einreichen/,
  // Fehlalarme vermeiden: das Wort Systemprompt allein ist kein Fund, nur mit nachfolgendem Inhalt oder einer Wiedergabe (Doppelpunkt, Anführungszeichen, lautet, sagt, verlangt ...); api key bleibt immer ein Fund
  /\bapi[ _-]?key\b|\b(?:system ?prompt|systemprompt)\b[^.\n]{0,12}?(?::|["„“»]|\b(?:lautet|lauten|sagt|besagt|verlangt|verbietet|schreibt vor)\b)/i
];
for (let i = 0; i < INTERN.length; i++) { if (INTERN[i].test(sichtbar)) funde.push('MUSTER_INTERN:' + i); }
// v06: eine Note ohne Aufruf von Qualitaet_pruefen ist behauptet, nicht belegt
if (NOTE_RE.test(hinweis + '\n' + rueckfrage) && !schritte.includes('Qualitaet_pruefen')) funde.push('NOTE_OHNE_PRUEFUNG');
// fremde Kunden (Stand 19.11.2026, eigener Kunde ordwin). Liste aller Kunden mit fester Zuordnung Muster zu Kuerzel; der eigene Kunde (Konfiguration, Feld kunde_kuerzel) wird ausgenommen, Funde nur fuer die uebrigen. Neuer Kunde: eine Zeile in KUNDEN ergaenzen.
const KUNDEN = [
  { kuerzel: 'KUNDE_B', muster: /KUNDE_B/i },
  { kuerzel: 'ordwin', muster: /\bordwin\b/i }
];
const eigenerKunde = String(cfg.kunde_kuerzel || '').trim().toLowerCase();
const FREMD = KUNDEN.map((k, nr) => ({ kuerzel: k.kuerzel, muster: k.muster, nr: nr })).filter(k => k.kuerzel !== eigenerKunde);
// Fehlalarme vermeiden: ein Name, den der Nutzer in dieser Anfrage selbst geschrieben hat, ist kein Fund; echte fremde Namen aus der Datenbank bleiben einer.
// Absicherung: ist der Eingabetext nicht erreichbar, bleibt eingabe leer und die Pruefung ist streng (ein genannter fremder Name bleibt ein Fund).
let eingabe = ''; try { eingabe = String($('Eingang vereinheitlichen [Code]').first().json.text || ''); } catch (e) { eingabe = ''; }
for (let i = 0; i < FREMD.length; i++) { if (FREMD[i].muster.test(sichtbar) && !FREMD[i].muster.test(eingabe)) funde.push('FREMDER_KUNDE:' + FREMD[i].nr); }

// M1 (13.11.2026): Beitraege, die das Werkzeug in diesem Lauf bestaetigt gespeichert hat (nur Erwartungswert fuer die Kontrolle)
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const beitraege = [];
for (const a of aufrufe) {
  if (a.tool !== 'Zur_Freigabe_einreichen' || !/^\s*STATUS:\s*OK/.test(a.obs)) continue;
  const m = /post_id:\s*([0-9a-f-]{36})/i.exec(a.obs);
  if (m && UUID.test(m[1]) && !beitraege.includes(m[1].toLowerCase())) beitraege.push(m[1].toLowerCase());
}
const qualitaet = QUALI(steps, postId);
const ok = funde.length === 0;
let text;
if (ok) {
  // B14: bei status auskunft ist die Antwort an den Menschen der Hinweis selbst (output aus hinweis_an_mensch)
  // v06: der Satz des Agenten zur Note wird entfernt, bei eingereicht steht die belegte Zeile aus QUALI
  text = daten.status === 'auskunft' ? hinweis : ['Status: ' + daten.status, OHNE_NOTE(hinweis), daten.status === 'eingereicht' ? qualitaet.zeile : '', rueckfrage ? 'Rückfrage: ' + rueckfrage : '', postId ? 'Beitrag: ' + postId : ''].filter(Boolean).join('\n');
} else {
  // M1: fester Satz, keine Funde, keine Muster, keine Modellfelder im Text
  text = 'Die Antwort des Agenten konnte nicht freigegeben werden. Es wurde nichts zur Freigabe vorgelegt. Der Lauf ist im Ausführungsprotokoll festgehalten.';
}
return [{ json: { output: text, pruefung_ok: ok, funde: funde, werkzeuge_aufgerufen: schritte, beitraege_beobachtet: beitraege, agent_json: daten, qualitaet: qualitaet, prompt_version: cfg.prompt_version, trace_id: cfg.trace_id } }];

// Fehlerweg des Agenten (R252): Der Agent ist ausgefallen (Zeitüberschreitung, Max iterations, Modellfehler).
// Warum: Der Lauf endet mit festem Ausfalltext statt mit einem Absturz. Die Ursache bleibt als Code im Lauf (Feld fehler_code), nie im Text für Menschen (R252, R52).
const j = $input.first().json || {};
const roh = typeof j.error === 'string' ? j.error : ((j.error && (j.error.message || j.error.description)) || j.message || '');
// Warum schwärzen: eine Fehlermeldung des Modells kann Schlüssel oder Tokens enthalten (R116).
const msg = String(roh).replace(/(sk-[A-Za-z0-9_-]{8,}|nvapi-[A-Za-z0-9_-]+|Bearer\s+[A-Za-z0-9._-]+|eyJ[A-Za-z0-9_-]{10,})/g, '[geschwärzt]').slice(0, 200);
let code = 'AGENT_FEHLER';
if (/max iterations/i.test(msg)) code = 'MAX_ITERATIONS';
else if (/timed? ?out|timeout|ETIMEDOUT|ESOCKETTIMEDOUT/i.test(msg)) code = 'ZEITUEBERSCHREITUNG';
else if (/429|rate limit/i.test(msg)) code = 'RATE_LIMIT';
else if (/402|payment|credit/i.test(msg)) code = 'GUTHABEN';
else if (/401|403|unauthor|forbidden|api key/i.test(msg)) code = 'ZUGANG';
const cfg = $('Konfiguration [Edit Fields]').first().json;
return [{ json: { fehler_code: code, fehler_kurz: msg, status: 'fehler', pruefung_ok: false, funde: ['AGENT_AUSGEFALLEN:' + code], werkzeuge_aufgerufen: [], agent_json: null, prompt_version: cfg.prompt_version, trace_id: cfg.trace_id } }];

// Zweck: die Freigabe aus der Datenbank vorbereiten, nicht aus dem Text des Agenten. Hier endet jede Abweichung als Fehler (Freigabe-Fehler).
// v07 (20.11.2026): Notenfilter wieder streng gegen behauptete Bewertungen in Ziffern (Bewertung 5 von 5 Punkten, 4,4 von 5 Qualitaetspunkten, Qualitaetspruefung 4 von 5), ohne echten Inhalt zu loeschen; Pruefgrenze 14 Aufrufe (maxIterations 16 bleibt; nachtraegliche Ausgabepruefung, keine harte Aufrufgrenze, gemessen 20.11.2026); Zeile "Achtung, Endtext ungeprueft". v07b (20.11.2026, F5): hinter der 5 folgt kein Dezimal- oder Tausendertrenner (4 von 5.000 und 4 von 5,5 sind keine Note, Bewertung 4 von 5, 4,4 von 5 und 4,4 von 5,0 bleiben Note).
// v07c (20.11.2026, Pruefrunde N2 und N3): 5,00 und 5.00 hinter "von" bleiben Note (5.000 und 5,005 nicht); Dezimalteile in den Zweigen Bewertung/Score und Qualitaetspruefung nur mit 1 bis 2 Nachkommastellen (Bewertung 5.000 Euro und Score 1.200 Zeichen sind keine Note).
// v06 (19.11.2026): die Zeile zur Qualitätsprüfung kommt aus den Zwischenschritten des Agenten (Rückgabe von Qualitaet_pruefen, QUALI), nur mit Note, wenn die letzte Prüfung genau das eingereichte Paket bewertet hat; sonst Endtext ungeprüft oder Prüfung ausgefallen. Der Satz des Agenten zur Note wird entfernt.
// QUALI v06 (19.11.2026): Note, Urteil und paket_id der Qualitaetspruefung aus den Rueckgaben von Qualitaet_pruefen (Zwischenschritte des Agenten), nie aus dem Satz des Agenten.
// Gilt nur fuer das eingereichte Paket: Note nur, wenn die letzte Pruefung genau dieses Paket bewertet hat. Sonst Endtext ungeprueft oder Pruefung ausgefallen, nie eine Note eines anderen Texts.
const QUALI = (steps, postId) => {
  const liste = Array.isArray(steps) ? steps : [];
  const zerlege = (o) => { let v = o; if (typeof v === 'string') { try { v = JSON.parse(v); } catch (e) { return { text: v, obj: null }; } } const l = Array.isArray(v) ? v : [v]; const obj = l.find(x => x && typeof x === 'object') || null; return { text: l.map(x => (x && typeof x === 'object') ? (typeof x.antwort === 'string' ? x.antwort : '') : String(x ?? '')).join('\n'), obj: obj }; };
  const pid = (t) => { const m = /paket_id:\s*(\S+)/.exec(String(t || '')); return m ? m[1].trim() : ''; };
  const urteilVon = (z) => {
    if (z.obj && typeof z.obj.error === 'string' && typeof z.obj.antwort !== 'string') return 'FEHLER';
    const t = z.text;
    if (/^\s*STATUS:\s*OK/.test(t)) return 'OK';
    if (/^\s*STATUS:\s*UEBERARBEITEN/.test(t)) return 'UEBERARBEITEN';
    if (/^\s*(STATUS:\s*)?NICHT_GEFUNDEN/.test(t)) return 'NICHT_GEFUNDEN';
    if (/^\s*(STATUS:\s*)?FEHLER/.test(t)) return 'FEHLER';
    return 'OHNE_STATUS';
  };
  const noteVon = (z) => {
    if (z.obj && typeof z.obj.note === 'number' && Number.isFinite(z.obj.note)) return z.obj.note;
    const m = /note:\s*([0-9]+(?:[.,][0-9]+)?)/i.exec(z.text);
    return m ? Number(m[1].replace(',', '.')) : null;
  };
  const pruefungen = [];
  let eingereicht = '', eingereichtOk = '';
  for (let i = 0; i < liste.length; i++) {
    const s = liste[i] || {}; const a = s.action || {}; const tool = String(a.tool || '');
    const ein = (a.toolInput && typeof a.toolInput === 'object' && typeof a.toolInput.paket_id === 'string') ? a.toolInput.paket_id.trim() : '';
    const z = zerlege(s.observation);
    if (tool === 'Qualitaet_pruefen') {
      const urteil = urteilVon(z);
      const note = (urteil === 'OK' || urteil === 'UEBERARBEITEN') ? noteVon(z) : null;
      pruefungen.push({ nr: i + 1, paket_id: pid(z.text) || ein, urteil: urteil, note: note });
