// Hinweis des Agenten ohne die Teile zur Note (die belegte Note setzt der Workflow); Saetze an Satzzeichen und Zeilenumbruch, Satzteile an Komma und Semikolon getrennt. Ein Satz ohne Notenteil bleibt zeichengleich; gross geschrieben wird nur, wenn am Satzanfang ein Teil entfernt wurde.
const OHNE_NOTE = (h) => String(h || '').replace(/[ \t]*\n+[ \t]*(?=\d)/g, ' ').split(/(?<=[.!?])\s+|\n+/).map(satz => { const t = satz.trim(); const ende = /[.!?]$/.test(t) ? t.slice(-1) : ''; const kern = ende ? t.slice(0, -1) : t; const alle = kern.split(/(?<=[,;])\s+/); const teile = alle.filter(x => x.trim() && !NOTE_TEIL.test(x.replace(/[,;]\s*$/, ''))); if (teile.length === alle.length) return t; if (!teile.length) return ''; const s = teile.join(' ').replace(/[,;]\s*$/, '').trim(); return (teile[0] !== alle[0] ? s.charAt(0).toUpperCase() + s.slice(1) : s) + ende; }).filter(Boolean).join(' ').trim();
const pr = $('Agent-Antwort prüfen [Code]').first().json;
const post = $('Beitrag laden [HTTP Request]').first().json || {};
const set = Array.isArray($input.first().json.body) ? $input.first().json.body : [];
const hole = k => String((set.find(r => r.setting_key === k) || {}).setting_value || '');
const chat = hole('telegram_chat_id'), nutzer = hole('telegram_freigabe_nutzer_id');
const cfg = $('Konfiguration [Edit Fields]').first().json;
if (!post.id || post.id !== pr.agent_json.post_id || post.status !== 'wartet_auf_freigabe' || post.erzeugt_von !== 'p2_agent') throw new Error('Freigabe: Der Beitrag in der Datenbank passt nicht zur Antwort des Agenten.');
if (String(post.execution_id) !== String(cfg.trace_id)) throw new Error('Freigabe: Der Beitrag gehört nicht zu diesem Lauf.');
if (!chat || !nutzer) throw new Error('Freigabe: Der Telegram-Zugang fehlt in den Einstellungen.');
const KI_HINWEIS = 'Dieser Beitrag wurde mit KI erstellt.';
if (post.ai_generated !== true || !String(post.caption_instagram || '').trimEnd().endsWith(KI_HINWEIS) || !String(post.linkedin_post || '').trimEnd().endsWith(KI_HINWEIS)) throw new Error('Freigabe: Die KI-Kennzeichnung fehlt im Beitrag.');
const pfade = (Array.isArray(post.slide_urls) ? post.slide_urls : []).concat(post.single_image_url ? [post.single_image_url] : []).map(String);
const hinweis = OHNE_NOTE(pr.agent_json.hinweis_an_mensch).slice(0, 300);
let steps = null; try { const a = $('Redaktions-Agent [AI Agent]').first().json || {}; steps = Array.isArray(a.intermediateSteps) ? a.intermediateSteps : null; } catch (e) { steps = null; }
const q = steps ? QUALI(steps, post.id) : { stand: 'ungeprueft', zeile: 'Qualitätsprüfung: Achtung, Endtext ungeprüft, die Rückgaben der Prüfung sind nicht lesbar.', eingereichtes_paket: '', paket_id: '', note: null, urteil: '', gilt_fuer_eingereicht: false, pruefungen: [] };
const sauber = (t) => String(t).replace(/_/g, '-').replace(/\*/g, 'x').replace(/`/g, "'").replace(/\[/g, '(').replace(/\]/g, ')');
const quelle = pfade.length ? 'Mit ' + pfade.length + ' Bildern.' : 'Ohne Bilder.';
const nachricht = sauber(('Freigabe für ' + cfg.kunde_kuerzel + ': ' + String(post.topic || '').slice(0, 200) + '. ' + quelle + (hinweis ? ' Hinweis: ' + hinweis : '')).slice(0, 700)) + '\n\n' + sauber(q.zeile) + '\n\nKI-Kennzeichnung (Text): vorhanden.';
return [{ json: { post_id: post.id, topic: String(post.topic || ''), kuerzel: cfg.kunde_kuerzel, trace_id: String(cfg.trace_id), chat_id: chat, nutzer_id: nutzer, pfade: pfade, bilder: pfade.length > 0, nachricht: nachricht, qualitaet_stand: q.stand, qualitaet_note: q.note, qualitaet_urteil: q.urteil, qualitaet_paket_id: q.paket_id, eingereichtes_paket: q.eingereichtes_paket } }];

// Zweck: alle Eingänge liefern dieselben Felder, damit Schwärzen und Prüfen nur einmal gebaut werden.
// Heute hängt nur der Chat-Eingang daran. Formular und Telegram (Block B) kommen an dieselbe Stelle.
const j = $input.first().json;
const text = String(j.chatInput ?? j.text ?? '').normalize('NFC');
const filterText = text.normalize('NFKC').replace(/[\p{Cf}͏ᅟᅠ឴឵᠋-᠏ㅤ︀-️ﾠ]/gu, '');
return [{ json: { text: text, filterText: filterText, eingang: 'chat', quellenart: 'Thema', session_id: String(j.sessionId ?? ('chat-' + $execution.id)), telegram_chat_id: '' } }];

