// Zweck: Hinweis auf die KI in der ersten Antwort einer Sitzung (Art. 50 Abs. 1 und 5 der KI-Verordnung). Der Hinweis kommt aus dem Workflow, nicht aus dem Modell.
// B4a (19.11.2026): alle Antworten laufen hier zusammen und gehen danach über Werkzeuge anzeigen und Antwort senden [Chat] an die Chat-Seite (responseMode responseNodes). Die Sofortantwort steht in der Liste ganz vorn.
// F5: wirft die Aufbereitung, geht trotzdem eine Antwort mit KI-Hinweis raus (eine Antwort ohne Hinweis ist verboten), mit festem Ersatztext.
const KI_HINWEIS = 'Hinweis: Du schreibst mit einer KI, nicht mit einem Menschen.';
const ENDEN = ['Sofortantwort setzen [Edit Fields]', 'Antwort setzen [Edit Fields]', 'Eingang abgelehnt [Edit Fields]', 'Antwort ohne Freigabe [Edit Fields]', 'Freigabe-Meldung gescheitert [Edit Fields]', 'Freigabe-Fehler [Edit Fields]', 'Ergebnis Sperre [Edit Fields]', 'Meldung fehlgeschlagen [Edit Fields]', 'Verwerfen gemeldet [Edit Fields]', 'Ergebnis Entscheidung [Edit Fields]', 'Ergebnis Ablage [Edit Fields]'];
try {
const hinweise = [];
let ende = '', antwort = '', felder = {};
for (const name of ENDEN) {
  try {
    const k = $(name); // wirft, wenn der Knoten (noch) nicht existiert, zum Beispiel der frühere Endknoten Antwort setzen
    if (k.isExecuted) { felder = k.first().json || {}; ende = name; antwort = String(felder.output ?? ''); break; }
  } catch (e) { hinweise.push(name + ': ' + String(e.message).slice(0, 80)); }
}
if (!ende || !antwort) throw new Error('KI-Hinweis: kein Endknoten mit Antwort gefunden (' + hinweise.length + ' nicht lesbar).');
// Alle Läufe von Sitzung prüfen in dieser Ausführung ansehen, Erfolgs- und Fehlerausgang: war einer "neu", ist das die erste Antwort der Sitzung.
const laeufe = [];
for (let i = 0; i <= $runIndex; i++) {
  for (const zweig of [0, 1]) {
    try { laeufe.push(...$('Sitzung prüfen [HTTP Request]').all(zweig, i).map(x => x.json || {})); }
    catch (e) { hinweise.push('Sitzung prüfen Zweig ' + zweig + ' Lauf ' + i + ': ' + String(e.message).slice(0, 80)); } // Zweig 1 fehlt eventuell im Erfolgsfall
  }
}
if (!laeufe.length) throw new Error('KI-Hinweis: kein Ergebnis von Sitzung prüfen.');
const gut = r => Number(r.statusCode) >= 200 && Number(r.statusCode) < 300 && Array.isArray(r.body);
const grund = laeufe.some(r => !gut(r)) ? 'unbekannt' : (laeufe.some(r => r.body.length > 0) ? 'neu' : 'bekannt');
const zeigen = grund !== 'bekannt'; // bei Fehler lieber zu viel als zu wenig
