const KANDIDATEN = ['Beitrag laden [HTTP Request]', 'Einstellungen laden [HTTP Request]', 'Freigabe vorbereiten [Code]', 'Vorschau-Adressen holen [HTTP Request]', 'Vorschau senden [Telegram]', 'Bilder einzeln [Code]', 'Bilder zusammenfassen [Code]', 'Instagram-Text senden [Telegram]', 'LinkedIn-Post senden [Telegram]', 'Freigabe abwarten [Telegram]', 'Status fertig setzen [HTTP Request]', 'Ablage-Elemente bauen [Code]', 'In Nextcloud ablegen [Execute Workflow]', 'Grund abfragen [Telegram]', 'Status abgelehnt setzen [HTTP Request]', 'Status abgelaufen setzen [HTTP Request]', 'Beitrag prüfen [Guardrails]', 'Beitrag sperren [HTTP Request]'];
