const status = (obs) => /^\s*STATUS:\s*OK/.test(obs) ? 'ok' : /^\s*STATUS:\s*UEBERARBEITEN/.test(obs) ? 'UEBERARBEITEN' : /^\s*(STATUS:\s*)?NICHT_GEFUNDEN/.test(obs) ? 'nicht gefunden' : /^\s*(STATUS:\s*)?FEHLER/.test(obs) ? 'Fehler' : 'ohne Status';
