const lief = n => { try { return $(n).isExecuted === true; } catch (e) { return false; } };
const erstes = n => { try { return lief(n) ? ($(n).first().json || {}) : null; } catch (e) { return null; } };
const eing = erstes('Eingang vereinheitlichen [Code]') || {};
const cfg = erstes('Konfiguration [Edit Fields]') || {};
const pr = erstes('Agent-Antwort prüfen [Code]');
const dj = pr && pr.agent_json && typeof pr.agent_json === 'object' ? pr.agent_json : null;
// F1 (20.11.2026, Gegenpruefung): Bei verworfener Ausgabe (pruefung_ok nicht true) stehen nur feste Fehlercodes im Protokoll, keine Modellfelder. Jeder Freitext wird vor dem Speichern geschwaerzt (Schluessel-Muster wie in Agent-Antwort pruefen plus lange Zeichenketten aus Buchstaben und Ziffern).
// F3 (20.11.2026, Gegenpruefung): scheitert Sperre melden, laeuft der Fehlerausgang ueber Ergebnis Sperre weiter; hier steht dann ein fester Hinweis.
const SCHWAERZ = [/sk-[A-Za-z0-9_-]{10,}/g, /nvapi-[A-Za-z0-9_-]*/gi, /eyJ[A-Za-z0-9_.-]{10,}/g, /sb_secret_[A-Za-z0-9_-]*/gi, /pplx-[A-Za-z0-9_-]*/gi, /Bearer\s+[A-Za-z0-9._-]{8,}/gi, /\b(?=[A-Za-z0-9_]*\d)(?=[A-Za-z0-9_]*[A-Za-z])[A-Za-z0-9_]{32,}\b/g];
const schwaerze = (t) => { let s = String(t ?? ''); for (const m of SCHWAERZ) s = s.replace(m, '[geschwärzt]'); return s; };
const CODE_RE = /^[A-Z][A-Z0-9_]*(?::[A-Za-z0-9_]{1,40})?$/;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const hinweise = [];
let toolentscheidung = pr && pr.pruefung_ok === true && dj && typeof dj.toolentscheidung === 'string' ? dj.toolentscheidung : '';
let status;
if (lief('Eingang abgelehnt [Edit Fields]') && !pr) status = 'abbruch_vor_agent';
else if (!pr) { status = lief('Ausfall festhalten [Code]') ? 'fehler' : 'abbruch_vor_agent'; if (status === 'fehler') hinweise.push('Agent ausgefallen'); }
else if (pr.pruefung_ok !== true) { status = 'fehler'; hinweise.push('Ausgabeprüfung: ' + (Array.isArray(pr.funde) && pr.funde.length ? pr.funde.map(f => CODE_RE.test(String(f)) ? String(f) : 'CODE_UNBEKANNT').join(',') : 'unklar')); }
else if (dj && dj.status === 'auskunft') { status = 'abgelehnt'; toolentscheidung = 'auskunft: ' + toolentscheidung; } // die Tabelle kennt auskunft nicht (Migration braucht Patricks Wort)
else status = dj && ['eingereicht', 'abgelehnt', 'rueckfrage', 'fehler'].includes(dj.status) ? dj.status : 'fehler';
if (pr && pr.pruefung_ok === true && dj && dj.status === 'fehler' && typeof dj.hinweis_an_mensch === 'string' && dj.hinweis_an_mensch) hinweise.push('Agent meldet fehler: ' + schwaerze(dj.hinweis_an_mensch).slice(0, 150));
if (lief('Ergebnis Sperre [Edit Fields]')) { status = 'fehler'; hinweise.push('Beitrag durch die Ausgangsprüfung gesperrt'); }
if (lief('Sperre melden [Telegram]')) { let gescheitert = false; try { gescheitert = $('Sperre melden [Telegram]').all(1).some(x => x && x.json && x.json.error); } catch (e) { gescheitert = false; } if (gescheitert) hinweise.push('Sperrmeldung an Patrick gescheitert'); }
