const entpacke = (o) => { let v = o; if (typeof v === 'string') { try { v = JSON.parse(v); } catch (e) { return v; } } const l = Array.isArray(v) ? v : [v]; return l.map(x => (x && typeof x === 'object') ? (typeof x.antwort === 'string' ? x.antwort : '') : String(x ?? '')).join('\n'); };
const stat = (obs) => /^\s*STATUS:\s*OK/.test(obs) ? 'ok' : /^\s*(STATUS:\s*)?NICHT_GEFUNDEN/.test(obs) ? 'nicht_gefunden' : /^\s*(STATUS:\s*)?FEHLER/.test(obs) ? 'fehler' : /^\s*STATUS:\s*UEBERARBEITEN/.test(obs) ? 'ueberarbeiten' : 'ohne_status';
const tools = steps.map(s => schwaerze(String((s && s.action && s.action.tool) || '?')).slice(0, 80));
